const body = $json.body ?? $json;
const raw = String(body.message ?? '');
const message = raw.replace(/[<>]/g, ' ').trim().slice(0, 1000);
if (!message || raw.length > 1200) return [{ json: { ok: false, error: { code: 'INVALID_PAYLOAD', message: 'La consulta no es válida.' } } }];
const locale = ['es','en','fr','pt','de'].includes(String(body.locale).split('-')[0]) ? String(body.locale).split('-')[0] : 'es';
const patterns = [
 ['emergency', /\b(911|9-1-1|emergenc|auxilio|socorro|help me|no respira|not breathing|sangr|bleeding|inconsciente|unconscious)\b/i],
 ['post_accident_support', /(nervios|ansiedad|panic|afraid|scared|después de un accidente|after an accident)/i],
 ['hospital', /(hospital|cl[ií]nica|clinic|farmacia|pharmacy)/i],
 ['weather', /(clima|tiempo|weather|lluvia|rain)/i],
 ['route_planning', /(ruta|route|recorrido|llegar|directions)/i],
 ['road_status', /(carretera|v[ií]a|road|tr[aá]fico|traffic|cerrad|blocked)/i],
 ['tourism', /(turis|visitar|playa|restaurante|caf[eé]|museo|touris|visit|beach)/i],
 ['translation', /(traduc|translate|translation)/i],
 ['incident_lookup', /(accidente|incidente|choque|collision|incident)/i],
 ['nearby_safety', /(cerca|alrededor|near me|nearby|peligro|danger)/i]
];
const intent = patterns.find(([, regex]) => regex.test(message))?.[0] ?? 'general_pulse';
const hasLocation = Number.isFinite(body.location?.lat) && Number.isFinite(body.location?.lng);
const needsLocation = ['nearby_safety','incident_lookup','hospital','weather','tourism'].includes(intent);
const context = body.context && typeof body.context === 'object' ? body.context : {};
const cards = [...(Array.isArray(context.nearbyIncidents) ? context.nearbyIncidents : []), ...(Array.isArray(context.nearbyRiskZones) ? context.nearbyRiskZones : []), ...(Array.isArray(context.activeAlerts) ? context.activeAlerts : [])].slice(0, 12);
const answers = {
 emergency: 'Si existe peligro inmediato, lesiones graves, dificultad para respirar, pérdida de conciencia o sangrado importante, llama al 9-1-1 ahora. PULSE no sustituye el despacho real.',
 post_accident_support: 'Primero confirma que estás fuera de peligro. Si hay lesiones o riesgo inmediato llama al 9-1-1. Si estás a salvo, respira lentamente y contacta a una persona de confianza. Esto no sustituye atención profesional.',
 location: 'Necesito tu ubicación para consultar datos cercanos verificados. Activa la ubicación; no se conservará un historial de movimientos.',
 nearby: cards.length ? `Encontré ${cards.length} elemento(s) en el contexto PULSE disponible. Revisa su fuente y actualización.` : 'No hay datos cercanos verificados en el contexto recibido. Esto no garantiza ausencia de riesgos.',
 general: 'Puedo ayudarte con incidentes, carreteras, rutas, hospitales, turismo, clima y orientación posterior a un accidente. No inventaré datos actuales.'
};
let answer = intent === 'emergency' ? answers.emergency : intent === 'post_accident_support' ? answers.post_accident_support : needsLocation && !hasLocation ? answers.location : ['nearby_safety','incident_lookup','hospital'].includes(intent) ? answers.nearby : answers.general;
if (locale === 'en') answer = intent === 'emergency' ? 'If there is immediate danger or a serious injury, call 9-1-1 now. PULSE does not replace real emergency dispatch.' : needsLocation && !hasLocation ? 'I need your location to check verified nearby data. Enable location; movement history will not be stored.' : cards.length ? `I found ${cards.length} item(s) in the available PULSE context. Check each source and update time.` : 'I can help with incidents, roads, routes, hospitals, tourism, weather, and post-accident guidance without inventing current facts.';
const normalizedCards = cards.map((card) => ({ ...card, sourceType: card.sourceType ?? 'pulse_verified' }));
return [{ json: { ok: true, intent, answer, spokenAnswer: answer, dataFreshness: new Date().toISOString(), generatedAt: new Date().toISOString(), engine: 'n8n-deterministic', sources: normalizedCards.map(({id,sourceType,updatedAt}) => ({id,sourceType,updatedAt})).filter((source) => source.id), cards: normalizedCards, mapActions: [], suggestedQuestions: [] } }];
